CREATE TABLE "tank_density_readings" ("id" TEXT NOT NULL,"organization_id" TEXT NOT NULL,"station_id" TEXT NOT NULL,"tank_id" TEXT NOT NULL,"density" DECIMAL(7,3) NOT NULL,"recorded_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"recorded_by_id" TEXT NOT NULL,CONSTRAINT "tank_density_readings_pkey" PRIMARY KEY ("id"),CONSTRAINT "tank_density_readings_organization_id_fkey" FOREIGN KEY ("organization_id") REFERENCES "organizations"("id") ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT "tank_density_readings_station_id_fkey" FOREIGN KEY ("station_id") REFERENCES "stations"("id") ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT "tank_density_readings_tank_id_fkey" FOREIGN KEY ("tank_id") REFERENCES "tanks"("id") ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT "tank_density_readings_recorded_by_id_fkey" FOREIGN KEY ("recorded_by_id") REFERENCES "users"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE INDEX "tank_density_readings_tank_id_recorded_at_idx" ON "tank_density_readings"("tank_id","recorded_at");
